    private Mc263AbandonedCampGrammarData() {
        throw new AssertionError("no instances");
    }

    static byte[] decode() throws IOException {
        byte[] compressed;
        try {
            compressed = Base64.getDecoder().decode(ENCODED);
        } catch (IllegalArgumentException error) {
            throw new IOException("Abandoned Camp semantic grammar base64 is malformed", error);
        }
        if (compressed.length != GZIP_BYTES || !GZIP_SHA256.equals(sha256(compressed))) {
            throw new IOException("Abandoned Camp semantic grammar gzip identity drift");
        }
        ByteArrayOutputStream output = new ByteArrayOutputStream(PAYLOAD_BYTES);
        try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(compressed))) {
            byte[] block = new byte[8192];
            for (int read; (read = gzip.read(block)) >= 0;) {
                if (read == 0) continue;
                if (output.size() + read > MAX_PAYLOAD_BYTES) {
                    throw new IOException("Abandoned Camp semantic grammar exceeds bounded payload");
                }
                output.write(block, 0, read);
            }
        }
        byte[] decoded = output.toByteArray();
        if (decoded.length != PAYLOAD_BYTES || !PAYLOAD_SHA256.equals(sha256(decoded))) {
            throw new IOException("Abandoned Camp semantic grammar payload identity drift");
        }
        return decoded;
    }

    private static String sha256(byte[] data) throws IOException {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 unavailable", impossible);
        }
    }
